  1185  /* Do a collated comparison of A and B.  */
  1186  static int
  1187  collated_compare (const void *a, const void *b)
  1188  {
  1189    char *const *ps1 = a; char *s1 = *ps1;
  1190    char *const *ps2 = b; char *s2 = *ps2;
  1191
  1192    if (s1 == s2)
